import React, { useState } from "react"; // react ke hooks ko import kar rahe hain
import axios from "axios"; //axios ek libarary hai jo HTTP requests ko handle karne ke liye use hoti hai
import { useNavigate } from "react-router-dom"; // ye jab submit button par click karte hain to redirect karta hai home page par uske liya use ata hain
import { GoogleLogin } from "@react-oauth/google"; // google sign in component import kar rahe hain
import { jwtDecode } from "jwt-decode"; // jwt token ko decode karne ke liye use hota hai
import OtpModal from "../components/OtpModels";
const Signup = () => {
  const navigate = useNavigate(); // ye ek hook hai jo humein navigation ke liye function deta hai

  const [formData, setFormData] = useState({   // useState hook ka use kar rahe hain data ko store karne ke liye
    username: "",
    email: "",
    password: ""
  });

  const handleChange = (e) => {  // matlab ye data ko input field se le raha hai aur formData ko update kar raha hai
    setFormData((prev) => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  const handleSubmit = async (e) => {
  e.preventDefault();
  try {
    const res = await axios.post("http://localhost:5000/api/users/signup", {
      name: formData.username,
      email: formData.email,
      password: formData.password
    });

    console.log("Signup success:", res.data);

    //  Show OTP modal after signup
    setUserEmailForOtp(res.data.email);
    setShowOtpModal(true);

  } catch (err) {
    console.error("Signup failed:", err.response?.data || err.message);
    alert("Signup failed. Please try again.");
  }
};

const [otp, setOtp] = useState("");


const [showOtpModal, setShowOtpModal] = useState(false);
const [userEmailForOtp, setUserEmailForOtp] = useState("");

const handleGoogleSignup = async (credentialResponse) => {
  try {
    const decoded = jwtDecode(credentialResponse.credential);

    const res = await axios.post("http://localhost:5000/api/users/google-signup", {
      name: decoded.name,
      email: decoded.email,
      picture: decoded.picture
    });

    // ✅ If OTP was sent, show OTP modal
    if (res.data.message.includes("OTP")) {
      setUserEmailForOtp(res.data.email);
      setShowOtpModal(true);
      return; // ⛔ wait for OTP verification first
    }

    // ✅ If token received directly (already verified)
    if (res.data.token) {
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("name", res.data.user.name);
      localStorage.setItem("email", res.data.user.email);
      localStorage.setItem("role", res.data.user.role);

      alert("Signed up with Google successfully!");
      navigate("/home", { state: { navigation_intent: true } });
    }
  } catch (err) {
    console.error("Google Signup Failed:", err.response?.data || err.message);
    alert("Google signup failed. Please try again.");
  }
};

const handleVerifyOtp = async (e) => {
  e.preventDefault();
  try {
    const response = await axios.post("http://localhost:5000/api/auth/verify-otp", {
      email: userEmailForOtp, // make sure this email is stored after signup
      otp,
    });

    if (response.data.success) {
      alert("OTP verified successfully!");
      setShowOtpModal(false);
      // optionally redirect or login user here
    } else {
      alert("Invalid OTP. Please try again.");
    }
  } catch (err) {
    console.error("Error verifying OTP:", err);
    alert("Something went wrong. Please try again later.");
  }
};


 return (
  <div style={{
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    height: "100vh",
    backgroundColor: "#f0f2f5"
  }}>
    <form onSubmit={handleSubmit} style={{
      backgroundColor: "#fff",
      padding: "30px",
      borderRadius: "10px",
      boxShadow: "0 0 10px rgba(0,0,0,0.1)",
      width: "350px"
    }}>
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>Signup</h1>

      <div style={{ marginBottom: "15px" }}>
        <label htmlFor="username" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Username:</label>
        <input
          type="text"
          id="username"
          name="username"
          required
          onChange={handleChange}
          value={formData.username}
          style={{
            width: "100%",
            padding: "8px",
            borderRadius: "5px",
            border: "1px solid #ccc"
          }}
        />
      </div>

      <div style={{ marginBottom: "15px" }}>
        <label htmlFor="email" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Email:</label>
        <input
          type="email"
          id="email"
          name="email"
          required
          onChange={handleChange}
          value={formData.email}
          style={{
            width: "100%",
            padding: "8px",
            borderRadius: "5px",
            border: "1px solid #ccc"
          }}
        />
      </div>

      <div style={{ marginBottom: "20px" }}>
        <label htmlFor="password" style={{ display: "block", marginBottom: "5px", fontWeight: "bold" }}>Password:</label>
        <input
          type="password"
          id="password"
          name="password"
          required
          onChange={handleChange}
          value={formData.password}
          style={{
            width: "100%",
            padding: "8px",
            borderRadius: "5px",
            border: "1px solid #ccc"
          }}
        />
      </div>

      <button type="submit" style={{
        width: "100%",
        padding: "10px",
        backgroundColor: "#007bff",
        color: "white",
        border: "none",
        borderRadius: "5px",
        fontWeight: "bold",
        cursor: "pointer"
      }}>
        Signup
      </button>

      {/* Google Sign-In button */}
      <div style={{ marginTop: "20px", textAlign: "center" }}>
        <GoogleLogin
          onSuccess={handleGoogleSignup}
          onError={() => {
            console.log("Google Signup Failed");
          }}
        />
      </div>

      <p style={{ marginTop: "15px", textAlign: "center" }}>
        Already have an account?{" "}
        <span
          onClick={() => navigate("/login", { state: { navigation_intent: true } })}
          style={{ color: "#007bff", textDecoration: "none", cursor: "pointer" }}
        >
          Login
        </span>
      </p>
    </form>
    {showOtpModal && (
  <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
    <div className="bg-white rounded-2xl shadow-lg p-6 w-full max-w-md relative">
      <h2 className="text-2xl font-semibold mb-4 text-center text-gray-800">Enter OTP</h2>
      <p className="text-sm text-gray-600 text-center mb-4">
        An OTP has been sent to <strong>{userEmailForOtp}</strong>
      </p>
      <form onSubmit={handleVerifyOtp}>
        <input
          type="text"
          placeholder="Enter 6-digit OTP"
          value={otp}
          onChange={(e) => setOtp(e.target.value)}
          className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 mb-4"
          maxLength={6}
          required
        />
        <button
          type="submit"
          className="w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 rounded-lg transition"
        >
          Verify OTP
        </button>
      </form>
      <button
        onClick={() => setShowOtpModal(false)}
        className="absolute top-2 right-3 text-gray-400 hover:text-gray-600 text-xl"
      >
        &times;
      </button>
    </div>
  </div>
)}


  </div>
);
};

export default Signup;
